import re
from datetime import datetime

_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}
_DIGITS = "0123456789"
_ANGLE_RE = re.compile(r"<([^<>]*)>")
_ZIP4_RE = re.compile(r"([0-9]{5})-([0-9]{4})")
_TAG_SPLIT_RE = re.compile(r"[;,]")


def _field(row, key):
    """Fetch a field as a stripped string ('' if missing or None)."""
    return (row.get(key) or "").strip()


def _is_ascii_digits(s):
    return bool(s) and all(c in _DIGITS for c in s)


def _normalize_email(raw):
    s = raw
    m = _ANGLE_RE.search(s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.replace(".", "")
            local = local.split("+", 1)[0]
            domain = "gmail.com"
        s = f"{local}@{domain}"
    return s


def _is_valid_email(s):
    if s.count("@") != 1:
        return False
    local, domain = s.split("@")
    return (
        bool(local)
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _normalize_phone(raw):
    s = raw.lower()
    cut = len(s)
    for marker in ("x", "ext", "#"):
        i = s.find(marker)
        if i != -1 and i < cut:
            cut = i
    digits = "".join(c for c in s[:cut] if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _is_valid_phone(digits):
    return len(digits) == 10 and digits[0] not in "01"


def _normalize_zip(raw):
    z = raw
    m = _ZIP4_RE.fullmatch(z)
    if m:
        z = m.group(1)
    if len(z) == 4 and _is_ascii_digits(z):
        z = "0" + z
    return z if len(z) == 5 and _is_ascii_digits(z) else ""


def _normalize_name(raw):
    s = raw
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw):
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(raw, fmt)
        except ValueError:
            pass
    return None  # unparseable: treated as oldest


def _parse_tags(raw):
    return {t.strip().lower() for t in _TAG_SPLIT_RE.split(raw) if t.strip()}


def _pick(recs, field):
    """Pick the value of `field` from the best row that has it non-empty.

    Preference: source == 'manual', then most recent `updated`, then earliest input row.
    """
    cands = [r for r in recs if r[field]]
    if not cands:
        return ""
    best = max(
        cands,
        key=lambda r: (
            r["source"] == "manual",
            r["updated"] or datetime.min,
            -r["index"],
        ),
    )
    return best[field]


def _merge_group(recs):
    tags = set()
    for r in recs:
        tags.update(r["tags"])

    updated_vals = [r["updated"] for r in recs if r["updated"] is not None]
    latest = max(updated_vals).strftime("%Y-%m-%d") if updated_vals else ""

    return {
        "first_name": _pick(recs, "first_name"),
        "last_name": _pick(recs, "last_name"),
        "zip": _pick(recs, "zip"),
        "email": _pick(recs, "email"),
        "phone": _pick(recs, "phone"),
        "source": _pick(recs, "source"),
        "tags": ";".join(sorted(tags)),
        "opted_out": "Y" if any(r["opted_out"] for r in recs) else "N",
        "updated": latest,
    }


def dedupe_contacts(rows):
    # Step 1: clean each row; drop rows with neither a valid email nor phone.
    # Invalid email/phone/zip values are stored as "" so that "non-empty" means "qualifies".
    cleaned = []
    for idx, row in enumerate(rows):
        email_norm = _normalize_email(_field(row, "email"))
        email = email_norm if _is_valid_email(email_norm) else ""

        phone_norm = _normalize_phone(_field(row, "phone"))
        phone = phone_norm if _is_valid_phone(phone_norm) else ""

        if not email and not phone:
            continue

        cleaned.append({
            "index": idx,
            "first_name": _normalize_name(_field(row, "first_name")),
            "last_name": _normalize_name(_field(row, "last_name")),
            "zip": _normalize_zip(_field(row, "zip")),
            "email": email,
            "phone": phone,
            "source": _field(row, "source").lower(),
            "tags": _parse_tags(_field(row, "tags")),
            "opted_out": _field(row, "opted_out").lower() in _OPT_OUT_VALUES,
            "updated": _parse_updated(_field(row, "updated")),
        })

    # Step 2: union-find over rows that match on email, or on phone + last name.
    n = len(cleaned)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    by_email = {}
    by_phone_last = {}
    for i, rec in enumerate(cleaned):
        if rec["email"]:
            by_email.setdefault(rec["email"], []).append(i)
        if rec["phone"] and rec["last_name"]:
            key = (rec["phone"], rec["last_name"].casefold())
            by_phone_last.setdefault(key, []).append(i)

    for bucket in list(by_email.values()) + list(by_phone_last.values()):
        for j in bucket[1:]:
            union(bucket[0], j)

    # Step 3: collect groups, ordered by each group's earliest input row.
    groups = {}
    for i in range(n):
        groups.setdefault(find(i), []).append(i)

    ordered = sorted(groups.values(), key=lambda members: cleaned[members[0]]["index"])

    # Step 4: merge each group into one output dict.
    return [_merge_group([cleaned[i] for i in members]) for members in ordered]
```

Notes on interpretation, since these affect output:

- **Missing or invalid values:** Invalid emails, phones, and ZIPs are stored as `""`, so they never win field selection. Missing keys or `None` are treated as `""`.
- **`source` selection:** A row qualifies for the `source` field only if its source is non-empty, following the rule that each field is picked from rows where that field is non-empty.
- **Unparseable `updated`:** A value that matches none of the three formats is treated as older than any valid date. If no row in a group has a valid date, `updated` is `""`.
- **Tags:** Tags are deduplicated as a set before sorting, since the rule describes a union.

